import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'

const AllRoomBlur = () => {

    let [ store, setStore ] = useState([]);

        const getdata = () => {
            try{
                fetch("http://localhost:1234/room")
                .then( res => res.json() )
                .then( info => {
                    setStore(info)
                })
            }catch(error){
                console.error(" Data fetching is not processed ")
            }
        }

        useEffect( () => {
            getdata()
        }, [])


    return(
        <div className="container mt-5 " >
            <h2 className="fw-bolder ms-md-5" > LIST OF ROOM AVAILABLE </h2>
            <div className="col-md-4 mt-4">
                <div className=" card hovers rounded-5 p-2"  >
                    <Skeleton height={240} width={`3%`} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" />
                    <div className=" card-body " >
                    <Skeleton height={340} count={5} width={`3%`} duration={0.8} baseColor="#c0c0c0" highlightColor="#f0f0f0" />
                    </div>
                </div>
            </div>
        </div>       
    )
}

export default AllRoomBlur
